set -e
mkdir -p .kronn
cat > /tmp/pulls.json
python3 -c "
import json
raw=json.load(open('/tmp/pulls.json'))
SKIP='skip-auto-review'
prs={}
stack=[raw]
while stack:
    x=stack.pop()
    if isinstance(x,list):
        stack.extend(x); continue
    if isinstance(x,dict):
        b=x.get('base')
        if 'number' in x and isinstance(b,dict):
            labels={(l.get('name') or '').lower() for l in (x.get('labels') or [])}
            repo=((b.get('repo') or {})).get('full_name','')
            num=x.get('number')
            author=(x.get('user') or {}).get('login','')
            head=(x.get('head') or {}).get('sha','')
            if (not x.get('draft')) and (SKIP not in labels) and (not author.endswith('[bot]')) and repo and num is not None:
                prs[(repo,num)]={'number':num,'baseRef':b.get('ref','main'),'author':author,'repo':repo,'head':head}
        else:
            stack.extend(x.values())
out=sorted(prs.values(), key=lambda d:(d['repo'],-d['number']))
json.dump(out, open('.kronn/prs_candidates.json','w'))
print(json.dumps(out))
"

python3 - "$(pwd)" <<'PY'
import json,glob,os,re,sys,urllib.request,datetime
# Coût + durée de chaque review : sessions Claude Code du step reason (~/.claude/projects/<worktree>) -> dataset
# collection "review_sessions" de la page récap, upsert sur session_id (republier met à jour, jamais de doublon).
# Usage : python3 - <worktree> | python3 - --all   (DRY_RUN=1 : affiche sans publier)
PAGE='@@review.page_id@@'; API='@@kronn.api@@'
# $/M tokens : entrée, sortie, cache lu, cache écrit 5 min, cache écrit 1 h. Sert UNIQUEMENT si la session n'a pas
# de coût réel (cost-state, absent des sessions antérieures au 24/09). Calé sur les coûts réels Opus 5.5 (écart 0 %).
RATES={'claude-opus-5-5':(4,20,0.2,5,8),'claude-opus-4-8':(5,25,0.5,6.25,10)}
ROOT=os.environ.get('REVIEW_SESSIONS_ROOT') or os.path.expanduser('~/.claude/projects/')
arg=sys.argv[1] if len(sys.argv)>1 else os.getcwd()
dirs=glob.glob(ROOT+'*kronn-worktrees*') if arg=='--all' else [ROOT+re.sub(r'[^A-Za-z0-9]','-',arg)]
def ms(ts):
    return datetime.datetime.fromisoformat(ts.replace('Z','+00:00')).timestamp()*1000
rows=[]; skipped=[]
for d in dirs:
    for f in glob.glob(d+'/*.jsonl'):
        first=None; cost=None; t0=t1=None; sid=None; seen={}
        for line in open(f,encoding='utf-8',errors='replace'):
            try: o=json.loads(line)
            except Exception: continue
            ts=o.get('timestamp')
            if ts: t0=t0 or ts; t1=ts
            sid=sid or o.get('sessionId')
            m=o.get('message') or {}
            if first is None and o.get('type')=='user':
                c=m.get('content'); first=c if isinstance(c,str) else json.dumps(c,ensure_ascii=False)
            if o.get('type')=='cost-state': cost=o
            if o.get('type')=='assistant' and m.get('usage') and m.get('model') and not m['model'].startswith('<'):
                seen[m.get('id') or len(seen)]=(m['model'],m['usage'])
        g=first and re.search(r'Review la PR #(\d+) \(`([^`]+)`',first)
        if not g or not (seen or cost): continue
        per={}
        for model,u in seen.values():
            cc=u.get('cache_creation') or {}; t=per.setdefault(model,[0,0,0,0,0])
            c5=cc.get('ephemeral_5m_input_tokens'); c1=cc.get('ephemeral_1h_input_tokens')
            if c5 is None and c1 is None: c5=u.get('cache_creation_input_tokens',0)
            for i,v in enumerate([u.get('input_tokens',0),u.get('output_tokens',0),u.get('cache_read_input_tokens',0),c5,c1]): t[i]+=v or 0
        if cost:
            usd=float(cost.get('totalCostUSD') or 0); est=False
            if not per:
                mu=cost.get('modelUsage') or {}
                per={k:[v.get('inputTokens',0),v.get('outputTokens',0),v.get('cacheReadInputTokens',0),v.get('cacheCreationInputTokens',0),0] for k,v in mu.items()}
        elif all(m in RATES for m in per):
            usd=sum(sum(a*b for a,b in zip(per[m],RATES[m]))/1e6 for m in per); est=True
        else:
            skipped.append(os.path.basename(f)+' (modèle sans tarif connu : '+', '.join(sorted(per))+')'); continue
        tot=[sum(p[i] for p in per.values()) for i in range(5)]
        rows.append({'session_id':sid or os.path.basename(f)[:-6],'repo':g[2],'pr':int(g[1]),
          'cost_usd':round(usd,4),'estimated':est,'model':max(per,key=lambda k:sum(per[k])) if per else '',
          'input':tot[0],'output':tot[1],'cache_read':tot[2],'cache_write':tot[3]+tot[4],
          'started_at':t0,'session_ms':int(ms(t1)-ms(t0)) if t0 and t1 else None,
          'api_ms':int(cost.get('totalAPIDuration') or 0) if cost else None})
for s in skipped: print('ignoré : '+s)
if not rows:
    print('review_sessions : aucune session de review dans '+(arg if arg!='--all' else 'les worktrees')); sys.exit(0)
rows.sort(key=lambda r:r['started_at'] or '')
if os.environ.get('DRY_RUN')=='1':
    print(json.dumps(rows[-3:],indent=1)); print('%d sessions, %.2f $'%(len(rows),sum(r['cost_usd'] for r in rows))); sys.exit(0)
for i in range(0,len(rows),100):
    body={'writes':[{'dataset':'review_sessions','operation':'upsert','value':rows[i:i+100],'key_field':'session_id'}]}
    req=urllib.request.Request(API+'/pages/'+PAGE+'/publish',data=json.dumps(body).encode(),headers={'Content-Type':'application/json'},method='POST')
    res=json.loads(urllib.request.urlopen(req,timeout=30).read().decode(),strict=False)
    if not res.get('success'): print('review_sessions ERREUR : '+str(res.get('error'))); sys.exit(1)
print('review_sessions OK : %d review(s), %.2f $'%(len(rows),sum(r['cost_usd'] for r in rows)))
PY
